const TechBadge = ({ tech }) => {
  const techLogo = TECH_LOGOS[tech.key];

  return (
    <span className="inline-flex items-center gap-1.5 px-2.5 py-1.5 rounded bg-gray-900 border-gray-500 text-sm text-white whitespace-nowrap">
      <span className={"inline-flex items-center justify-center w-5 h5"}>
        {techLogo}
      </span>
      {tech.name}
    </span>
  );
};

export default TechBadge;
